CloseContractUseCase- repository: BrokerageContractRepository
- eventPublisher: ApplicationEventPublisher+ close(contractId): void {
var contract = repository.findById(contractId);
contract.close();
repository.save(contract);
eventPublisher.publishEvent(
new ContractSigned(contract.getId(),
contract.getPropertyId(), contract.getClosedAt()));
}
